    private static final String JSON="blocks/base.json",OBJECT="objects/model.iob";
    private static byte[] bytes(String text) { return text.getBytes(StandardCharsets.UTF_8); }
    private static void check(boolean valid,String reason) { if (!valid) throw new AssertionError("Background Save Copy: "+reason); }
    @FunctionalInterface private interface Action { void run() throws Exception; }
    private static void rejects(Action action) throws Exception { try { action.run(); } catch (IOException | IllegalArgumentException | IllegalStateException | NullPointerException expected) { return; }throw new AssertionError("Expected rejected folder copy"); }
    private static void cancelled(Action action) throws Exception { try { action.run(); } catch (CancellationException expected) { return; }throw new AssertionError("Expected cancelled folder copy"); }
    private static PackWorkspace pack() throws Exception { return PackWorkspace.newPack(Map.of(JSON,bytes("{\r\n\"block\":\"minecraft:stone\",\"future\":9007199254740993,\"literal\":\"雪\\u0061\"\r\n}"),OBJECT,new byte[]{0,-1,4,9},"future/raw.json",bytes("invalid unknown JSON\r\n"),"empty.raw",new byte[0])); }
    private static FolderCopies.Receipt copy(ZipExportSource source,Path target) throws Exception { return FolderCopies.copy(source,target,new ZipExports.Control(),(a,b) -> {}); }
    private static void same(PackWorkspace actual,Map<String,byte[]> expected) { check(actual.paths().equals(expected.keySet()),"exact copied file set");for (var entry : expected.entrySet()) check(Arrays.equals(actual.read(entry.getKey()),entry.getValue()),"exact copied bytes "+entry.getKey()); }
    private static Map<String,byte[]> content(PackWorkspace pack) { var files=new LinkedHashMap<String,byte[]>();for (String path : pack.paths()) files.put(path,pack.read(path));return files; }
    private static boolean empty(Path path) throws Exception { try (var entries=Files.list(path)) { return entries.findAny().isEmpty(); } }
    private static List<Path> staging(Path parent) throws Exception { try (var entries=Files.list(parent)) { return entries.filter(p->p.getFileName().toString().startsWith(".iris-copy-")).toList(); } }
    private static void noStaging(Path parent) throws Exception { check(staging(parent).isEmpty(),"known staging entries cleaned up"); }
