        for (int i=1;i<counts.size();i++) check(counts.get(i)>=counts.get(i-1) && sizes.get(i)>=sizes.get(i-1),"monotonic copy progress");check(counts.getLast()==captured.summary().entries() && sizes.getLast()==captured.summary().bytes(),"exact source-entry and copied-byte totals");
