    private static void guards(Path temp) throws Exception {
        Path root=Files.createDirectory(temp.resolve("folder-copy-guards"));var source=pack().captureZipExport();Path occupied=Files.createDirectory(root.resolve("occupied"));Files.write(occupied.resolve("keep.raw"),new byte[]{77});Path file=Files.write(root.resolve("file.raw"),new byte[]{88});rejects(() -> copy(source,occupied));rejects(() -> copy(source,file));rejects(() -> copy(source,file.resolve("child")));rejects(() -> FolderCopies.copy(source,null,new ZipExports.Control(),(a,b) -> {}));check(Files.readAllBytes(occupied.resolve("keep.raw"))[0]==77 && Files.readAllBytes(file)[0]==88,"occupied/file/invalid-parent guards preserve bytes");noStaging(root);
        Path late=Files.createDirectory(root.resolve("late"));var added=new AtomicBoolean();rejects(() -> FolderCopies.copy(source,late,new ZipExports.Control(),(entries,bytes) -> { if (bytes>0 && added.compareAndSet(false,true)) try { Files.write(late.resolve("foreign.raw"),new byte[]{66}); } catch (IOException failure) { throw new UncheckedIOException(failure); } }));check(Files.readAllBytes(late.resolve("foreign.raw"))[0]==66,"new child in empty target is preserved; no partial copy published");noStaging(root);
        Path appeared=root.resolve("appeared");var once=new AtomicBoolean();rejects(() -> FolderCopies.copy(source,appeared,new ZipExports.Control(),(entries,bytes) -> { if (bytes>0 && once.compareAndSet(false,true)) try { Files.createDirectory(appeared); } catch (IOException failure) { throw new UncheckedIOException(failure); } }));check(empty(appeared),"an initially absent destination appearing during staging is refused");noStaging(root);
        Path identity=Files.createDirectory(root.resolve("identity"));var time=Files.getLastModifiedTime(identity);Object key=Files.readAttributes(identity,java.nio.file.attribute.BasicFileAttributes.class).fileKey();var changed=new AtomicBoolean();if (key!=null) { rejects(() -> FolderCopies.copy(source,identity,new ZipExports.Control(),(entries,bytes) -> { if (bytes>0 && changed.compareAndSet(false,true)) try { Path alternate=Files.createDirectory(root.resolve("alternate"));Files.delete(identity);Files.move(alternate,identity);Files.setLastModifiedTime(identity,time); } catch (IOException failure) { throw new UncheckedIOException(failure); } }));check(empty(identity),"same-mtime replaced directory identity is rejected"); }noStaging(root);
        Path restore=Files.createDirectory(root.resolve("restore"));var control=new ZipExports.Control();rejects(() -> FolderCopies.copy(source,restore,control,(a,b)->{},(staging,destination)->{throw new IOException("injected move failure");}));check(Files.isDirectory(restore) && empty(restore) && !control.publishing(),"failed publication restores an old empty target and closes publication state");noStaging(root);
        Path missingParents=root.resolve("fresh/parent/output");rejects(() -> FolderCopies.copy(source,missingParents,new ZipExports.Control(),(a,b)->{},(staging,destination)->{throw new IOException("injected new-target move failure");}));check(!Files.exists(root.resolve("fresh")),"failed new-target move removes newly created empty parents");noStaging(root);
        Path raced=Files.createDirectory(root.resolve("raced"));rejects(() -> FolderCopies.copy(source,raced,new ZipExports.Control(),(a,b)->{},(staging,destination)->{Files.createDirectory(destination);Files.write(destination.resolve("other.raw"),new byte[]{55});Files.move(staging,destination);}));check(Files.readAllBytes(raced.resolve("other.raw"))[0]==55 && !Files.exists(raced.resolve(JSON)),"competing destination during publication is preserved without replacement or restoration over its contents");noStaging(root);
        Path invalid=Files.createDirectory(root.resolve("invalid"));Object originalKey=Files.readAttributes(invalid,java.nio.file.attribute.BasicFileAttributes.class).fileKey();var bad=PackWorkspace.newPack(Map.of("blocks/"+"a".repeat(300)+".json",new byte[]{1})).captureZipExport();rejects(() -> copy(bad,invalid));check(empty(invalid) && java.util.Objects.equals(originalKey,Files.readAttributes(invalid,java.nio.file.attribute.BasicFileAttributes.class).fileKey()),"actual staging write failure preserves original empty target identity");noStaging(root);
        Path real=Files.createDirectory(root.resolve("real")),link=root.resolve("link");boolean linked=false;try { Files.createSymbolicLink(link,real);linked=true; } catch (UnsupportedOperationException | java.nio.file.FileSystemException unavailable) { }if (linked) { rejects(() -> copy(source,link));rejects(() -> copy(source,link.resolve("child")));check(empty(real),"destination and ancestor symbolic links refused"); }noStaging(root);
    }
    private static void cancellationAndOwnership(Path temp) throws Exception {
        Path root=Files.createDirectory(temp.resolve("folder-copy-cancel"));var source=PackWorkspace.newPack(Map.of("large.raw",new byte[256*1024],"later.raw",new byte[]{1})).captureZipExport();Path target=root.resolve("cancelled");var early=new ZipExports.Control();check(early.cancel(),"early cancel accepted");cancelled(() -> FolderCopies.copy(source,target,early,(a,b)->{}));check(!Files.exists(target),"pre-start cancellation creates no destination");noStaging(root);
        Path existing=Files.createDirectory(root.resolve("existing"));var control=new ZipExports.Control();cancelled(() -> FolderCopies.copy(source,existing,control,(entries,bytes)->{if(bytes>0)check(control.cancel(),"stream cancel accepted");}));check(empty(existing),"stream cancellation preserves original empty target");noStaging(root);
        var publication=new ZipExports.Control();Path committed=root.resolve("committed");var receipt=FolderCopies.copy(source,committed,publication,(a,b)->{},(stage,destination)->{check(publication.publishing() && !publication.cancel(),"publication closes cancellation window");Files.move(stage,destination);});check(receipt.directory().equals(committed.toRealPath()) && !publication.cancel() && !publication.publishing(),"completed copy remains authoritative after late cancel");noStaging(root);
        // Cleanup never recursively removes foreign content unexpectedly added inside its private staging tree.
        var stop=new ZipExports.Control();var injected=new AtomicBoolean();var leftover=new AtomicReference<Path>();Path noOutput=root.resolve("no-output");rejects(() -> FolderCopies.copy(source,noOutput,stop,(entries,bytes)->{if(bytes>0 && injected.compareAndSet(false,true))try{Path stage=staging(root).getFirst();leftover.set(stage);Files.write(stage.resolve("foreign.raw"),new byte[]{44});stop.cancel();}catch(Exception failure){throw new RuntimeException(failure);}}));check(!Files.exists(noOutput) && Files.readAllBytes(leftover.get().resolve("foreign.raw"))[0]==44 && !Files.exists(leftover.get().resolve("large.raw")),"unknown staging child preserved, owned partial file removed, no destination published");Files.delete(leftover.get().resolve("foreign.raw"));Files.delete(leftover.get());noStaging(root);
        // Replacing a tracked file with a different identity is detected on filesystems exposing file keys.
        var probe=pack().captureZipExport();Path protectedOutput=root.resolve("protected-output");var preserved=new AtomicReference<Path>();rejects(() -> FolderCopies.copy(probe,protectedOutput,new ZipExports.Control(),(a,b)->{},(stage,destination)->{Path owned=stage.resolve(JSON);if(Files.readAttributes(owned,java.nio.file.attribute.BasicFileAttributes.class).fileKey()!=null){Path replacement=stage.resolve("replacement.raw");Files.write(replacement,new byte[]{33});Files.move(replacement,owned,StandardCopyOption.REPLACE_EXISTING);preserved.set(owned);}throw new IOException("injected publication failure");}));if(preserved.get()!=null){check(Files.readAllBytes(preserved.get())[0]==33,"changed tracked file identity left intact");Path stage=preserved.get().getParent().getParent();Files.delete(preserved.get());Files.delete(preserved.get().getParent());Files.delete(stage);}noStaging(root);
    }
    private static final class Gate { final CountDownLatch started=new CountDownLatch(1),release=new CountDownLatch(1); }
    private static void await(CountDownLatch latch,String reason) throws Exception { check(latch.await(10,TimeUnit.SECONDS),reason); }
    private static void releaseIgnoringInterrupt(Gate gate) { long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);boolean released=false;while(!released && System.nanoTime()<deadline)try{released=gate.release.await(20,TimeUnit.MILLISECONDS);}catch(InterruptedException ignored){}check(released,"controlled copy released"); }
    private static java.util.concurrent.ThreadFactory threads(AtomicReference<Thread> holder) { return runnable->{var worker=new Thread(runnable,"test-folder-copy");holder.set(worker);return worker;}; }
    private static void stop(Thread worker) throws Exception { worker.join(10_000);check(!worker.isAlive(),"worker exits after returning"); }
    private static AsyncFolderCopy.Snapshot terminal(AsyncFolderCopy copy) throws Exception { long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);do{var state=copy.poll();if(state.phase()!=AsyncFolderCopy.Phase.COPYING && state.phase()!=AsyncFolderCopy.Phase.CANCELLING && state.phase()!=AsyncFolderCopy.Phase.PUBLISHING)return state;LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(1));}while(System.nanoTime()<deadline);throw new AssertionError("copy worker timeout"); }
    private static void workers(Path temp) throws Exception {
        Path root=Files.createDirectory(temp.resolve("folder-copy-workers"));var current=pack();current.save(root.resolve("active"));var expected=content(current);var drafts=new InspectorDrafts();drafts.update("late","saved","draft");var gate=new Gate();var holder=new AtomicReference<Thread>();Thread caller=Thread.currentThread();Path target=root.resolve("snapshot");
        try(var copy=new AsyncFolderCopy((source,destination,control,progress)->{check(Thread.currentThread()!=caller,"disk copy runs off UI with detached source");gate.started.countDown();releaseIgnoringInterrupt(gate);return FolderCopies.copy(source,destination,control,progress);},threads(holder))){check(copy.poll().phase()==AsyncFolderCopy.Phase.IDLE && !copy.busy(),"poll never starts writes");var initial=copy.start(current,target);await(gate.started,"writer starts");check(holder.get().isDaemon(),"daemon worker");rejects(()->copy.start(current,root.resolve("queued")));rejects(()->copy.start(current,null));rejects(copy::clear);check(copy.poll().request()==initial.request(),"busy/invalid requests retain active work with no hidden queue");current.replace(JSON,bytes("later applied edit"));current.saveCopy(root.resolve("ordinary-copy"));current.saveAs(root.resolve("as"));current.save(current.directory());current.replace(JSON,bytes("retained edit history"));var steps=current.historySteps(false);long revision=current.revision(),saved=current.saveRevision();var other=pack();check(other.revision()!=current.revision() && copy.poll().source().equals(initial.source()),"pinned capture survives Save/Copy/As, edits and workspace replacement");gate.release.countDown();var complete=terminal(copy);check(complete.phase()==AsyncFolderCopy.Phase.SUCCEEDED && complete.receipt().source().equals(initial.source()),"success receipt belongs to pinned capture");same(PackWorkspace.open(target),expected);check(current.revision()==revision && current.saveRevision()==saved && current.historySteps(false).equals(steps) && drafts.any(),"worker completion retains current baseline/history/drafts");for(int i=0;i<20;i++)check(copy.poll()==complete,"stable completed receipt");copy.clear();check(copy.poll().phase()==AsyncFolderCopy.Phase.IDLE,"clear completed receipt");}stop(holder.get());
        var blocked=new Gate();var cancelThread=new AtomicReference<Thread>();Path cancelledTarget=root.resolve("noncooperative");try(var copy=new AsyncFolderCopy((source,destination,control,progress)->{blocked.started.countDown();releaseIgnoringInterrupt(blocked);return new FolderCopies.Receipt(destination,source.summary());},threads(cancelThread))){copy.start(current,cancelledTarget);await(blocked.started,"noncooperative starts");check(copy.cancel() && copy.poll().phase()==AsyncFolderCopy.Phase.CANCELLING && cancelThread.get().isAlive(),"cancel does not join noncooperative writer");rejects(()->copy.start(current,root.resolve("not-queued")));blocked.release.countDown();var state=terminal(copy);check(state.phase()==AsyncFolderCopy.Phase.CANCELLED && state.receipt()==null && !Files.exists(cancelledTarget),"cancelled writer cannot publish stale success metadata");}stop(cancelThread.get());
        var publishing=new Gate();var publishingThread=new AtomicReference<Thread>();Path published=root.resolve("publishing");try(var copy=new AsyncFolderCopy((source,destination,control,progress)->FolderCopies.copy(source,destination,control,progress,(stage,output)->{publishing.started.countDown();releaseIgnoringInterrupt(publishing);Files.move(stage,output);}),threads(publishingThread))){copy.start(current,published);await(publishing.started,"publication starts");check(copy.poll().phase()==AsyncFolderCopy.Phase.PUBLISHING && !copy.cancel(),"publication phase is noncancellable");publishing.release.countDown();check(terminal(copy).phase()==AsyncFolderCopy.Phase.SUCCEEDED && Files.isDirectory(published),"authorized publication completes after late cancel");}stop(publishingThread.get());
        var calls=new AtomicInteger();var failureThread=new AtomicReference<Thread>();try(var copy=new AsyncFolderCopy((source,destination,control,progress)->{int n=calls.incrementAndGet();if(n==1)throw new IOException("bad\n"+"x".repeat(2000));if(n==2)return null;return FolderCopies.copy(source,destination,control,progress);},threads(failureThread))){copy.start(current,root.resolve("retry"));var failed=terminal(copy);check(failed.phase()==AsyncFolderCopy.Phase.FAILED && !failed.detail().contains("\n") && failed.detail().length()<=515,"escaped bounded errors");for(int i=0;i<20;i++)check(copy.poll()==failed && calls.get()==1,"stable error without automatic retries");copy.start(current,root.resolve("retry"));check(terminal(copy).phase()==AsyncFolderCopy.Phase.FAILED,"null receipt rejected");copy.start(current,root.resolve("retry"));check(terminal(copy).phase()==AsyncFolderCopy.Phase.SUCCEEDED,"explicit retry recovery");}stop(failureThread.get());
        var closeGate=new Gate();var closeThread=new AtomicReference<Thread>();Path closeTarget=root.resolve("closed");var closing=new AsyncFolderCopy((source,destination,control,progress)->{closeGate.started.countDown();releaseIgnoringInterrupt(closeGate);return FolderCopies.copy(source,destination,control,progress);},threads(closeThread));closing.start(current,closeTarget);await(closeGate.started,"close active");closing.close();closing.close();check(closing.poll().phase()==AsyncFolderCopy.Phase.CLOSED && closeThread.get().isAlive(),"close cancels without joining blocked writer");rejects(()->closing.start(current,root.resolve("closed-request")));closeGate.release.countDown();stop(closeThread.get());check(!Files.exists(closeTarget),"closed pre-publication copy creates no destination");noStaging(root);
        try(var actual=new AsyncFolderCopy()){actual.start(current,root.resolve("actual"));check(terminal(actual).phase()==AsyncFolderCopy.Phase.SUCCEEDED,"production background copy");}noStaging(root);
    }
    static void run(Path temp) throws Exception { snapshots(temp);guards(temp);cancellationAndOwnership(temp);workers(temp);System.out.println("PASS: staged background Save Copy with exact captured unknown/opaque/empty-folder bytes, pinned snapshots across edits/Save/New-Open, new/empty/deep destination and overlap/link/identity/late-content guards, nonrecursive publication and empty-target restoration, actual write/move failure isolation, known-entry-only cleanup with foreign content/identity preservation, cancellation/publication boundary, one active snapshot/no hidden queue, stable errors/explicit retry/nonblocking close, separate guarded opening and unchanged drafts/history/dirty/save baselines; no native generation"); }
